def classify(text):
    try:
        parsed = datetime.fromisoformat(text)
    except ValueError:
        return "invalid"
    return "aware" if parsed.tzinfo is not None else "naive"


json.dump(
    [{"text": text, "result": classify(text)} for text in CASES],
    sys.stdout,
    ensure_ascii=True,
    indent=1,
)
sys.stdout.write("\n")
